            auto chart=b.reference;S free=(b.strip.lo+b.strip.hi)/S(2),eta=(b.eta_lo+b.eta_hi)/S(2);auto old_point=target::strip_point(m,chart,faces,a,b.strip,free,eta,false);sd::AffineAngular correlated;correlated.slope=S(Q(1)/Q(3));correlated.intercept=old_point.s*(old_point.t-correlated.slope);auto new_point=sd::evaluate(m,chart,old_point.s,old_point.t,&correlated);
            auto compare=[&](S x,S y){need(fabsq(x.n-y.n)<=sf::add(x.e,y.e),"regular-q coordinates preserve original field/value/AD2");coordinate_comparisons++;};
            for(int k=0;k<2;k++){compare(old_point.value.field.position[k],new_point.field.position[k]);compare(old_point.value.field.velocity[k],new_point.field.velocity[k]);for(int i=0;i<2;i++)for(int j=0;j<2;j++){compare(old_point.value.Hx[k][i][j],new_point.Hx[k][i][j]);compare(old_point.value.Hv[k][i][j],new_point.Hv[k][i][j]);}}for(int k=0;k<4;k++){compare(old_point.value.field.F[k],new_point.field.F[k]);compare(old_point.value.field.V[k],new_point.field.V[k]);compare(old_point.value.field.grad_v[k],new_point.field.grad_v[k]);}compare(old_point.value.field.J,new_point.field.J);
